package it.frociart.app;
import java.util.*;import java.nio.file.*;import java.nio.charset.*;import static it.frociart.app.FlowModel.*;
public class TurtleTests {
 static int checks;static String current;static Path root;
 static void eq(Object expected,Object actual){checks++;if(!Objects.equals(expected,actual))throw new AssertionError(current+": expected ["+expected+"] actual ["+actual+"]");}
 static void near(double expected,double actual){checks++;if(Double.isNaN(actual)||Math.abs(expected-actual)>1e-8)throw new AssertionError(current+": expected "+expected+" actual "+actual);}
 static double num(String s){return Double.parseDouble(s);}static String decode(String s){return new String(Base64.getDecoder().decode(s),StandardCharsets.UTF_8);}
 static void rejects(Runnable a){boolean rejected=false;try{a.run();}catch(FlowEngine.Problem ex){rejected=true;}eq(true,rejected);}
 static void shared()throws Exception{for(String row:Files.readAllLines(root.resolve("cases.tsv"),StandardCharsets.UTF_8)){String[] f=row.split("\t",-1);current=f[0];Document original=FlowPseudocode.decode(decode(f[1]));Files.createDirectories(root.resolve("java-files"));Files.write(root.resolve("java-files").resolve(current+".frociart"),FlowCodec.encode(original).getBytes(StandardCharsets.UTF_8));Path other=root.resolve("pc-files").resolve(current+".frociart");
  for(int pass=0;pass<(Files.exists(other)?4:3);pass++){
   Document doc=pass==0?original:pass==1?FlowPseudocode.decode(FlowPseudocode.encode(original)):pass==2?FlowCodec.decode(FlowCodec.encode(original)):FlowCodec.decode(new String(Files.readAllBytes(other),StandardCharsets.UTF_8));FlowEngine.Runner r=new FlowEngine.Runner(doc);String[] inputs=decode(f[2]).isEmpty()?new String[0]:decode(f[2]).split("\u001e",-1);int used=0;
   for(int i=0;i<20000&&r.state!=FlowEngine.State.COMPLETED&&r.state!=FlowEngine.State.ERROR;i++){
    if(r.state==FlowEngine.State.WAITING||r.state==FlowEngine.State.WAITING_FILE){FlowTurtle.Snapshot before=r.turtle.capture();int steps=r.steps;for(int tick=0;tick<4;tick++)eq(false,r.step());eq(before.revision,r.turtle.revision());eq(steps,r.steps);eq(true,used<inputs.length);String input=inputs[used++];
     if(r.state==FlowEngine.State.WAITING){eq("I:",input.substring(0,2));eq(true,r.submitInput(input.substring(2)));}else{eq("F:",input.substring(0,2));eq(true,r.provideFile(r.pendingFile(),input.substring(2)));}
    }else r.step();
   }
   String error=decode(f[8]);eq(error.isEmpty()?FlowEngine.State.COMPLETED:FlowEngine.State.ERROR,r.state);if(!error.isEmpty())eq(true,r.errorMessage!=null&&r.errorMessage.toLowerCase(Locale.ROOT).contains(error.toLowerCase(Locale.ROOT)));
   eq(inputs.length,used);near(num(f[3]),r.turtle.x());near(num(f[4]),r.turtle.y());near(num(f[5]),r.turtle.heading());eq(f[6],r.turtle.color());eq(decode(f[9]),String.join("|",r.output));
   String[] lines=decode(f[7]).isEmpty()?new String[0]:decode(f[7]).split("\n");eq(lines.length,r.turtle.segments().size());for(int i=0;i<lines.length;i++){String[] l=lines[i].split(",");FlowTurtle.Segment s=r.turtle.segments().get(i);near(num(l[0]),s.x1);near(num(l[1]),s.y1);near(num(l[2]),s.x2);near(num(l[3]),s.y2);eq(l[4],s.color);}
   FlowTurtle.Snapshot saved=r.turtle.capture();long revision=r.turtle.revision();r.reset();eq(FlowEngine.State.READY,r.state);eq(false,r.turtle.used());near(0,r.turtle.x());near(0,r.turtle.y());near(90,r.turtle.heading());eq("#000000",r.turtle.color());eq(0,r.turtle.segments().size());eq(true,r.turtle.revision()>revision);eq(lines.length,saved.segments.size());
  }
 }}
 static void invariants(){current="atomic-errors-and-bounds";FlowTurtle t=new FlowTurtle();FlowTurtle.Spec forward=FlowTurtle.parse(TURTLE_FORWARD,"1"),turn=FlowTurtle.parse(TURTLE_TURN,"DESTRA 90"),pen=FlowTurtle.parse(TURTLE_PEN,"\"blu\"");
  t.apply(forward,FlowEngine.Value.number(1));FlowTurtle.Snapshot shot=t.capture();for(FlowEngine.Value bad:new FlowEngine.Value[]{FlowEngine.Value.bool(true),FlowEngine.Value.text("1"),null}){rejects(()->t.apply(forward,bad));rejects(()->t.apply(turn,bad));}rejects(()->t.apply(pen,FlowEngine.Value.number(4)));rejects(()->t.apply(pen,FlowEngine.Value.text("bad")));eq(shot.revision,t.revision());near(shot.y,t.y());near(shot.heading,t.heading());eq(shot.color,t.color());eq(1,t.segments().size());
  boolean readOnly=false;try{t.segments().clear();}catch(UnsupportedOperationException ex){readOnly=true;}eq(true,readOnly);readOnly=false;try{shot.segments.clear();}catch(UnsupportedOperationException ex){readOnly=true;}eq(true,readOnly);
  t.reset();for(int i=0;i<FlowTurtle.MAX_SEGMENTS;i++)t.apply(forward,FlowEngine.Value.number(i%2==0?1:-1));long revision=t.revision();rejects(()->t.apply(forward,FlowEngine.Value.number(1)));eq(FlowTurtle.MAX_SEGMENTS,t.segments().size());eq(revision,t.revision());near(0,t.y());t.apply(FlowTurtle.parse(TURTLE_FORWARD,"SENZA_TRACCIA 2"),FlowEngine.Value.number(2));near(2,t.y());eq(FlowTurtle.MAX_SEGMENTS,t.segments().size());t.apply(FlowTurtle.parse(TURTLE_CLEAR,"Pulisci"),null);t.apply(forward,FlowEngine.Value.number(1));eq(1,t.segments().size());
  for(int kind:new int[]{TURTLE_FORWARD,TURTLE_TURN,TURTLE_PEN})rejects(()->FlowTurtle.parse(kind,""));rejects(()->FlowTurtle.parse(TURTLE_TURN,"UP 90"));
  current="rename-preserves-syntax";Map<String,String> names=new TreeMap<>(String.CASE_INSENSITIVE_ORDER);names.put("destra","angolo");names.put("SENZA_TRACCIA","distanza");names.put("blu","colore");Node node=new Node();node.kind=TURTLE_TURN;eq("  DESTRA angolo",FlowDeclaration.rewriteNode(node,"  DESTRA destra",names));node.kind=TURTLE_FORWARD;eq("SENZA_TRACCIA distanza",FlowDeclaration.rewriteNode(node,"SENZA_TRACCIA SENZA_TRACCIA",names));node.kind=TURTLE_PEN;eq("\"blu\"",FlowDeclaration.rewriteNode(node,"\"blu\"",names));eq("colore",FlowDeclaration.rewriteNode(node,"blu",names));
 }
 static void debugger(){current="breakpoint-before-draw";Document doc=FlowPseudocode.decode("AVANZA 4\nRUOTA DESTRA 90\nAVANZA 5");for(Node n:doc.nodes)if(n.kind==TURTLE_FORWARD){n.breakpoint=true;break;}FlowEngine.Runner r=new FlowEngine.Runner(doc);FlowDebugger d=new FlowDebugger(r,doc);d.begin(FlowDebugger.Command.CONTINUE);for(int i=0;i<20&&d.active();i++)d.tick();eq(true,d.atBreakpoint());eq(0,r.turtle.segments().size());d.begin(FlowDebugger.Command.INTO);for(int i=0;i<20&&d.active();i++)d.tick();eq(1,r.turtle.segments().size());near(4,r.turtle.y());d.begin(FlowDebugger.Command.CONTINUE);for(int i=0;i<20&&d.active();i++)d.tick();eq(FlowEngine.State.COMPLETED,r.state);eq(2,r.turtle.segments().size());near(5,r.turtle.x());}
 public static void main(String[] args)throws Exception{root=Paths.get(args[0]);shared();invariants();debugger();System.out.println("TurtleTests PASS "+checks+" assertions");}
}
